const ticketStatuses=['new','open','waiting','resolved','closed'],ticketPriorities=['low','normal','high','urgent'];
const manage=r=>['truselv_admin','facility_admin'].includes(r),facilityStructure=r=>['facility_admin','facility_head'].includes(r),residents=r=>['truselv_admin','facility_admin','facility_head','activities_lead'].includes(r);
