 if(url.pathname==='/api/device/events'&&request.method==='POST'){const d=await device(request,env);if(d.status!=='active'||d.licence_status!=='active')return fail('This device is not active.',403);if(!d.ward_id)return fail('This device must be assigned to a ward.',403);const events=(await input(request)).events;if(!Array.isArray(events)||!events.length||events.length>100)return fail('Send between 1 and 100 events.');const writes=[];for(const e of events){if(!/^[a-zA-Z0-9-]{16,64}$/.test(e.id||'')||!text(e.feature,80)||!text(e.eventName,80)||!Number.isFinite(Number(e.durationSeconds))||Number(e.durationSeconds)<0||Number(e.durationSeconds)>86400||Number.isNaN(Date.parse(e.occurredAt)))return fail('One or more usage events are invalid.');if(e.sessionId){const session=await env.DB.prepare("SELECT id FROM activity_sessions WHERE id=? AND device_id=? AND status='active'").bind(e.sessionId,d.id).first();if(!session)return fail('A usage event references an inactive session.');}writes.push(env.DB.prepare('INSERT OR IGNORE INTO usage_events (id,facility_id,device_id,ward_id,resident_id,session_id,feature,event_name,duration_seconds,occurred_at) VALUES (?,?,?,?,?,?,?,?,?,?)').bind(e.id,d.facility_id,d.id,d.ward_id,null,e.sessionId||null,e.feature.trim(),e.eventName.trim(),Math.floor(Number(e.durationSeconds)),new Date(e.occurredAt).toISOString()));}await env.DB.batch(writes);await env.DB.prepare('UPDATE devices SET last_seen_at=? WHERE id=?').bind(now(),d.id).run();return json({accepted:events.length},202);}
